import{_ as n,c as a,o as t,ae as i}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Get Admin Menu (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-menu-gql","title":"Get Admin Menu","query":"query {\\n  getAdminMenu {\\n    id\\n    tree\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"getAdminMenu\\": {\\n      \\"id\\": \\"menu\\",\\n      \\"tree\\": [\\n        {\\n          \\"key\\": \\"dashboard\\",\\n          \\"label\\": \\"Dashboard\\",\\n          \\"icon\\": \\"icon-dashboard\\",\\n          \\"sort\\": 1,\\n          \\"permission\\": \\"dashboard\\",\\n          \\"apiResource\\": { \\"rest\\": \\"/api/admin/dashboard/stats\\", \\"graphql\\": \\"statsAdminDashboard\\" },\\n          \\"children\\": []\\n        },\\n        {\\n          \\"key\\": \\"sales\\",\\n          \\"label\\": \\"Sales\\",\\n          \\"icon\\": \\"icon-sales\\",\\n          \\"sort\\": 2,\\n          \\"permission\\": \\"sales\\",\\n          \\"apiResource\\": null,\\n          \\"children\\": [\\n            {\\n              \\"key\\": \\"sales.orders\\",\\n              \\"label\\": \\"Orders\\",\\n              \\"icon\\": null,\\n              \\"sort\\": 1,\\n              \\"permission\\": \\"sales.orders\\",\\n              \\"apiResource\\": { \\"rest\\": \\"/api/admin/orders\\", \\"graphql\\": \\"adminOrders\\" },\\n              \\"children\\": []\\n            },\\n            {\\n              \\"key\\": \\"sales.shipments\\",\\n              \\"label\\": \\"Shipments\\",\\n              \\"icon\\": null,\\n              \\"sort\\": 2,\\n              \\"permission\\": \\"sales.shipments\\",\\n              \\"apiResource\\": { \\"rest\\": \\"/api/admin/shipments\\", \\"graphql\\": \\"adminShipments\\" },\\n              \\"children\\": []\\n            }\\n          ]\\n        },\\n        {\\n          \\"key\\": \\"catalog\\",\\n          \\"label\\": \\"Catalog\\",\\n          \\"icon\\": \\"icon-catalog\\",\\n          \\"sort\\": 3,\\n          \\"permission\\": \\"catalog\\",\\n          \\"apiResource\\": null,\\n          \\"children\\": [\\n            {\\n              \\"key\\": \\"catalog.products\\",\\n              \\"label\\": \\"Products\\",\\n              \\"icon\\": null,\\n              \\"sort\\": 1,\\n              \\"permission\\": \\"catalog.products\\",\\n              \\"apiResource\\": { \\"rest\\": \\"/api/admin/catalog/products\\", \\"graphql\\": \\"adminCatalogProducts\\" },\\n              \\"children\\": []\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/navigation/menu.md","filePath":"api/graphql-api/admin/navigation/menu.md"}'),o={name:"api/graphql-api/admin/navigation/menu.md"};function r(s,e,d,l,c,p){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="get-admin-menu-graphql" tabindex="-1">Get Admin Menu (GraphQL) <a class="header-anchor" href="#get-admin-menu-graphql" aria-label="Permalink to &quot;Get Admin Menu (GraphQL)&quot;">​</a></h1><p>Returns the admin sidebar as a nested tree, filtered to what the authenticated token&#39;s role is allowed to see. Use it to build a back-office navigation/sidebar dynamically and to discover which API operation backs each screen.</p><h2 id="output-fields" tabindex="-1">Output Fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Identifier of the menu payload (<code>menu</code>).</td></tr><tr><td><code>tree</code></td><td>JSON</td><td>The nested menu structure.</td></tr></tbody></table><p><code>tree</code> is returned as a JSON structure — query it as a bare field, not a sub-selection.</p><p>Each node in <code>tree</code> (and in any nested <code>children</code>) carries <code>key</code>, <code>label</code>, <code>icon</code>, <code>sort</code>, <code>permission</code>, <code>apiResource</code>, and <code>children</code>. When present, <code>apiResource</code> maps the node to its backing endpoint as <code>{ rest, graphql }</code>; it is <code>null</code> for group headers (parent menus that only contain children) and for panel-only screens that have no API counterpart.</p><h2 id="permission-filtering" tabindex="-1">Permission Filtering <a class="header-anchor" href="#permission-filtering" aria-label="Permalink to &quot;Permission Filtering&quot;">​</a></h2><p>The tree is scoped to the token&#39;s role:</p><ul><li>A token whose permission type is <code>all</code> sees every menu node.</li><li>A token with custom permissions sees only the nodes its role permits; menus it cannot access are omitted entirely.</li></ul><p>So two admins with different roles will receive different trees from the same operation.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const m=n(o,[["render",r]]);export{u as __pageData,m as default};
